//! The generated start form of a code (R-D13: "its form generated by
//! `impress-verb-surface`, grouped by `x-run.group`"): the code's emitted
//! parameter schema fed to [`impress_verb_surface::schema_fields`], a Run
//! button that calls `run-service_start` with the fields as `params`, and
//! the answer bound to `state.result`. No logic of its own: the same
//! field-per-property rule every verb form uses, with the sections the
//! schema's groups ask for.

use impress_surface::spec::{Action, Button, Node, NodeKind, SurfaceSpec, SURFACE_VERSION};
use impress_verb_surface::{bind_slug, schema_fields};
use serde_json::{json, Map, Value};

use crate::codes::CodeProvider;

/// The state path the parameters live under.
pub const PARAMS_STATE: &str = "state.params";

/// The start form of `code`.
pub fn start_form(code: &CodeProvider) -> SurfaceSpec {
    // Prefill every field with the schema's default.
    let defaults: Map<String, Value> = code
        .properties()
        .iter()
        .filter_map(|(n, p)| p.get("default").map(|d| (n.clone(), d.clone())))
        .collect();
    let fields = schema_fields(&code.schema, &Value::Object(defaults.clone()), PARAMS_STATE);

    let mut params_args = Map::new();
    let mut params_state = Map::new();
    for (name, prop) in code.properties() {
        let slug = bind_slug(name);
        params_args.insert(
            name.clone(),
            Value::String(format!("{{{{{PARAMS_STATE}.{slug}}}}}")),
        );
        params_state.insert(
            slug,
            defaults
                .get(name)
                .cloned()
                .unwrap_or_else(|| empty_for(prop)),
        );
    }

    let description = code
        .schema
        .get("description")
        .and_then(Value::as_str)
        .unwrap_or("");
    let mut column: Vec<Node> = vec![Node::leaf(NodeKind::Text(format!(
        "**Start {} {}**\n\n{description}",
        code.name, code.version
    )))
    .with_id("description")];
    column.extend(fields);
    column.push(
        Node::leaf(NodeKind::Button(Button {
            label: "Run".to_string(),
            on_click: vec![Action::Call {
                verb: "run-service_start".to_string(),
                args: json!({
                    "code": code.name,
                    "params": Value::Object(params_args),
                    "name": "{{state.name}}",
                }),
                into: Some("state.result".to_string()),
                each: None,
                adverbs: None,
            }],
        }))
        .with_id("run"),
    );
    column.push(
        Node::leaf(NodeKind::Kv(json!("{{state.result}}")))
            .with_id("result")
            .with_label("Result"),
    );

    SurfaceSpec {
        surface: SURFACE_VERSION.to_string(),
        name: format!("Start {}", code.name),
        params: Vec::new(),
        state: json!({
            "params": Value::Object(params_state),
            "name": "",
            "result": Value::Null,
        }),
        sources: Default::default(),
        root: Node::leaf(NodeKind::Column(column)).with_id("root"),
        extra: Default::default(),
    }
}

/// An empty initial value for a property without a default, by type.
fn empty_for(prop: &Value) -> Value {
    match prop.get("type").and_then(Value::as_str) {
        Some("string") => json!(""),
        Some("boolean") => json!(false),
        Some("array") => json!([]),
        Some("object") => json!({}),
        _ => Value::Null,
    }
}
